// Compute triangular membrane stiffness matrix (6x6) in GLOBAL coordinates
// Then rotate each 2x2 nodal block using material angle
Eigen::Matrix<double, 6, 6> compute_triangle_stiffness_global(
    const std::vector<std::vector<double>>& coords,
    double e, double nu, double t) {

    // coords[i] = {x_i, y_i} for i=0,1,2 (3 nodes)
    double x1 = coords[0][0], y1 = coords[0][1];
    double x2 = coords[1][0], y2 = coords[1][1];
    double x3 = coords[2][0], y3 = coords[2][1];

    // Compute area of triangle
    double area = 0.5 * std::abs((x2-x1)*(y3-y1) - (x3-x1)*(y2-y1));
    if (area == 0.0) {
        return Eigen::Matrix<double, 6, 6>::Zero();
    }

    // Material matrix D for plane stress (3x3)
    double denom = 1.0 - nu*nu;
    double d11 = e / denom;
    double d12 = e * nu / denom;
    double d22 = e / denom;
    double d66 = e / (2.0 * (1.0 + nu));

    Eigen::Matrix<double, 3, 3> d_matrix;
    d_matrix << d11, d12, 0.0,
                d12, d22, 0.0,
                0.0, 0.0, d66;

    // Strain-displacement matrix B (3x6)
    // For linear triangle: B = [b1 0 b2 0 b3 0; 0 c1 0 c2 0 c3; c1 b1 c2 b2 c3 b3] / (2*area)
    double b1 = y2 - y3;
    double b2 = y3 - y1;
    double b3 = y1 - y2;
    double c1 = x3 - x2;
    double c2 = x1 - x3;
    double c3 = x2 - x1;

    Eigen::Matrix<double, 3, 6> b;
    b.setZero();
    b(0,0) = b1; b(0,2) = b2; b(0,4) = b3;
    b(1,1) = c1; b(1,3) = c2; b(1,5) = c3;
    b(2,0) = c1; b(2,1) = b1; b(2,2) = c2; b(2,3) = b2; b(2,4) = c3; b(2,5) = b3;
    b /= (2.0 * area);

    // Stiffness: K = t * area * B^T * D * B
    Eigen::Matrix<double, 6, 6> k_local = t * area * b.transpose() * d_matrix * b;

    // Now rotate each 2x2 nodal block: K_rot = T^T * K_local * T, where T = block-diag(R,R,R)
    // R = [[costh, -sinth], [sinth, costh]]
    double c = common.costh;
    double s = common.sinth;
    Eigen::Matrix<double, 2, 2> r;
    r << c, -s,
         s,  c;

    Eigen::Matrix<double, 6, 6> t_mat = Eigen::Matrix<double, 6, 6>::Zero();
    t_mat.block<2,2>(0,0) = r;
    t_mat.block<2,2>(2,2) = r;
    t_mat.block<2,2>(4,4) = r;

    Eigen::Matrix<double, 6, 6> k_global = t_mat.transpose() * k_local * t_mat;

    return k_global;
}

// Main CQUAD4 stiffness computation via 2-triangle decomposition
Eigen::Matrix<double, 8, 8> compute_cquad4_stiffness(
    const std::vector<std::vector<double>>& nodes,
    double e, double nu, double t) {

    // Split quad into two triangles: (0,1,2) and (0,2,3)
    // Triangle 1: nodes 0,1,2
    std::vector<std::vector<double>> tri1 = {nodes[0], nodes[1], nodes[2]};
    // Triangle 2: nodes 0,2,3
    std::vector<std::vector<double>> tri2 = {nodes[0], nodes[2], nodes[3]};

    // Compute stiffness for each triangle
    Eigen::Matrix<double, 6, 6> k_tri1 = compute_triangle_stiffness_global(tri1, e, nu, t);
    Eigen::Matrix<double, 6, 6> k_tri2 = compute_triangle_stiffness_global(tri2, e, nu, t);

    // Assemble into 8x8 global matrix
    // Node mapping: node i -> DOFs [2*i, 2*i+1]
    // Triangle 1 uses nodes [0,1,2] -> DOFs [0,1, 2,3, 4,5]
    // Triangle 2 uses nodes [0,2,3] -> DOFs [0,1, 4,5, 6,7]
    Eigen::Matrix<double, 8, 8> k_global = Eigen::Matrix<double, 8, 8>::Zero();

    // Add triangle 1
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int gi = 2 * i;      // global DOF index for u of node i
            int gj = 2 * j;      // global DOF index for u of node j
            // u-u block
            k_global(gi, gj) += k_tri1(2*i, 2*j);
            k_global(gi, gj+1) += k_tri1(2*i, 2*j+1);
            k_global(gi+1, gj) += k_tri1(2*i+1, 2*j);
            k_global(gi+1, gj+1) += k_tri1(2*i+1, 2*j+1);
        }
    }

    // Add triangle 2: node mapping [0->0, 2->1, 3->2] in tri2 local index
    // So local node 0 -> global node 0 -> DOFs 0,1
    // local node 1 -> global node 2 -> DOFs 4,5
    // local node 2 -> global node 3 -> DOFs 6,7
    std::vector<int> tri2_global_node = {0, 2, 3};
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int gi_u = 2 * tri2_global_node[i];
            int gj_u = 2 * tri2_global_node[j];
            k_global(gi_u,     gj_u)     += k_tri2(2*i, 2*j);
            k_global(gi_u,     gj_u+1)  += k_tri2(2*i, 2*j+1);
            k_global(gi_u+1,   gj_u)     += k_tri2(2*i+1, 2*j);
            k_global(gi_u+1,   gj_u+1)  += k_tri2(2*i+1, 2*j+1);
        }
    }

    return k_global;
}

